def is_sorted(lst):
    if len(lst) <= 1:
        return True

    for i in range(len(lst)):
        if lst[i] < lst[i-1]:
            return False

        # Check for duplicates more than once allowed (strictly ascending with at most one duplicate per value? 
        # Wait, re-read docstring: "If list has more than 1 duplicate of the same number, return False."
        # This means if a number appears >=3 times -> False. If it appears exactly twice -> True (as long as sorted).

    from collections import Counter
    counts = Counter(lst)

    for count in counts.values():
        if count > 2:
            return False

    return True
